def parse_host(h):
    if not h or len(h) > 253:
        return None
    labels = h.split(".")
    if len(labels) < 2:
        return None
    last = len(labels) - 1
    for i, lab in enumerate(labels):
        n = len(lab)
        if n < 1 or n > 63:
            return None
        for c in lab:
            if c not in LDH:
                return None
        if lab[0] == "-" or lab[-1] == "-":
            return None
        if i == last and lab[0] not in ASCII_LETTERS:
            return None
    return h.lower()


def parse_port(p):
    n = len(p)
    if n < 1 or n > 5:
        return None
    for c in p:
        if c not in DIGITS:
            return None
    v = int(p)
    if v < 1 or v > 65535:
        return None
    return str(v)


def parse_sip(s):
    """Canonical form of a SIP/SIPS URI, or None."""
    if s[:5].lower() == "sips:":
        sch = "sips"
        rest = s[5:]
    elif s[:4].lower() == "sip:":
        sch = "sip"
        rest = s[4:]
    else:
        return None
    at = rest.find("@")
    if at < 0:
        return None
    user_raw = rest[:at]
    hp = rest[at + 1:]
    if "@" in hp:
        return None
    out = []
    i = 0
    n = len(user_raw)
    while i < n:
        c = user_raw[i]
        if c == "%":
            if i + 2 >= n:
                return None
            a = user_raw[i + 1]
            b = user_raw[i + 2]
            if a not in HEXDIG or b not in HEXDIG:
                return None
            ch = chr(int(user_raw[i + 1:i + 3], 16))
            if ch not in USER_CHARS:
                return None
            out.append(ch)
            i += 3
        elif c in USER_CHARS:
            out.append(c)
            i += 1
        else:
            return None
    if not (1 <= len(out) <= 64):
        return None
    user = "".join(out)
    ci = hp.find(":")
    if ci < 0:
        host_raw, port = hp, ""
    else:
        if hp.find(":", ci + 1) >= 0:
            return None
        host_raw = hp[:ci]
        port = parse_port(hp[ci + 1:])
        if port is None:
            return None
        port = ":" + port
    host = parse_host(host_raw)
    if host is None:
        return None
    return sch + ":" + user + "@" + host + port


def parse_tel(s):
    body = s[4:]
    if not body.startswith("+"):
        return None
    digits = []
    for c in body[1:]:
        if c in DIGITS:
            digits.append(c)
        elif c == "-" or c == "." or c == "(" or c == ")":
            continue
        else:
            return None
    nd = len(digits)
    if nd < 3 or nd > 15:
        return None
    if digits[0] == "0":
        return None
    return "tel:+" + "".join(digits)


def parse_uri(s):
    """Canonical form of a SIP/SIPS/tel URI, or None."""
    if s[:4].lower() == "tel:":
        return parse_tel(s)
    if s[:5].lower() == "sips:" or s[:4].lower() == "sip:":
        return parse_sip(s)
    return None


def uri_kind(canon):
    """'sip' for SIP/SIPS canonical URIs, 'tel' for telephone URIs."""
    if canon[:4] == "tel:":
        return "tel"
    return "sip"


